const emails = $input.first().json.Attendees_Gmails
  .split(',').map(e => e.trim()).filter(e => e.length > 0);

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const invalidEmails = emails.filter(e => !emailRegex.test(e));

return [{
  json: {
    totalEmailsCount: emails.length,
    validEmailsCount: emails.length - invalidEmails.length,
    emails: emails,
    invalidEmails: invalidEmails
  }
}];

const formData = $('On form submission').first().json;
const duration = formData.Duration;

let durationInMinutes = 0;

if (duration.includes('hour') || duration.includes('hr')) {
  const num = parseFloat(duration);
  durationInMinutes = num * 60;
} else if (duration.includes('min')) {
  durationInMinutes = parseInt(duration);
}

return [{
  json: {
    ...formData,
    durationInMinutes: durationInMinutes
  }
}];

const newStart = new Date($('Edit Fields').first().json.DateTime).getTime();
const newDuration = $('Edit Fields').first().json.durationInMinutes;
const newEnd = newStart + (newDuration * 60000);

const existingMeetings = $input.all();
let conflict = false;
let conflictDetails = {};

for (const meeting of existingMeetings) {
  const m = meeting.json;
  if (m.Status === 'Cancelled') continue;
  const exStart = new Date(m['Date/Time']).getTime();
  const exDuration = parseInt(m['Duration(mins)']) || 0;
  const exEnd = exStart + (exDuration * 60000);
  const gap1 = newStart - exEnd;
  const gap2 = exStart - newEnd;
  if (gap1 < 3600000 && gap2 < 3600000) {
    conflict = true;
    conflictDetails = { title: m.Title, dateTime: m['Date/Time'], duration: exDuration };
    break;
  }
}

return [{ json: { ...$('Edit Fields').first().json, conflict, conflictDetails } }];

const now = Date.now();

const pastMeetings = $input.all().filter(item => {
  const m = item.json;
  const startTime = new Date(m['Date/Time']).getTime();
  const duration = parseInt(m['Duration(mins)']) || 0;
  const endTime = startTime + (duration * 60000);
  return endTime < now;
});

return pastMeetings.map(item => ({ json: item.json }));

const now = DateTime.now().setZone('Asia/Karachi');
const startOfWeek = now.startOf('week');
const endOfWeek = now.endOf('week');

const meetings = $input.all().filter(item => {
  const dt = DateTime.fromISO(item.json['Date/Time'], { zone: 'Asia/Karachi' });
  return dt >= startOfWeek && dt <= endOfWeek;
});

if (meetings.length === 0) {
  return [{ json: { html: '<p>No meetings scheduled this week.</p>' } }];
}

let rows = '';
for (const m of meetings) {
  rows += `<tr>
    <td>${m.json.Title}</td>
    <td>${m.json['Date/Time']}</td>
    <td>${m.json.Attendees}</td>
    <td>${m.json.Status}</td>
    <td>${m.json.Gist}</td>
  </tr>`;
}

const html = `
<h2>Weekly Meeting Digest</h2>
<table border="1" cellpadding="8" cellspacing="0">
  <tr>
    <th>Title</th><th>Date/Time</th><th>Attendees</th><th>Status</th><th>Gist</th>
  </tr>
  ${rows}
</table>`;

return [{ json: { html } }];

const now = Date.now();
const thirtyDays = 30 * 24 * 60 * 60 * 1000;

const oldMeetings = $input.all().filter(item => {
  const m = item.json;
  if (m.Status !== 'Done') return false;
  const meetingTime = new Date(m['Date/Time']).getTime();
  return (now - meetingTime) > thirtyDays;
});

return oldMeetings.map(item => ({
  json: {
    ...item.json,
    ArchivedOn: new Date().toISOString()
  }
}));

const items = $input.all();

items.sort((a, b) => {
  return b.json.row_number - a.json.row_number;
});

return items.map(item => ({ json: item.json }));
